import{f as r,o as t,c as e,aj as i}from"./chunks/framework.CJTJR_Xv.js";const o="/assets/Array%E5%86%85%E5%AD%98%E7%BB%93%E6%9E%84%E7%A4%BA%E6%84%8F%E5%9B%BE.CROks9Ut.png",f=JSON.parse('{"title":"JavaScript 中的 Array、Uint8Array 和 bitSet","description":"记录一下 JavaScript 中的 Array、Uint8Array 和 bitSet 数据结构，比较了它们的特点和使用场景。","frontmatter":{"title":"JavaScript 中的 Array、Uint8Array 和 bitSet","date":"2026-04-25T00:00:00.000Z","description":"记录一下 JavaScript 中的 Array、Uint8Array 和 bitSet 数据结构，比较了它们的特点和使用场景。","tags":["JavaScript"]},"headers":[],"relativePath":"posts/JavaScript中的 Array Uint8Array 和 bitSet.md","filePath":"posts/JavaScript中的 Array Uint8Array 和 bitSet.md","lastUpdated":1788599939000}'),c={name:"posts/JavaScript中的 Array Uint8Array 和 bitSet.md"};function l(n,a,s,d,p,y){return t(),e("div",null,a[0]||(a[0]=[i('<h1 id="javascript-中的-array、uint8array-和-bitset-底层原理与工程选型" tabindex="-1">JavaScript 中的 <code>Array</code>、<code>Uint8Array</code> 和 <code>bitSet</code> 底层原理与工程选型 <a class="header-anchor" href="#javascript-中的-array、uint8array-和-bitset-底层原理与工程选型" aria-label="Permalink to &quot;JavaScript 中的 `Array`、`Uint8Array` 和 `bitSet` 底层原理与工程选型&quot;">​</a></h1><p>在进行算法的练习与日常开发中，我们常常需要使用布尔数组来标记元素的状态。在 JavaScript 中，常见的选择有：</p><ol><li><strong>普通数组</strong>：<code>Array(n).fill(false)</code></li><li><strong>类型化数组</strong>：<code>Uint8Array(n)</code></li><li><strong>位压缩实现</strong>：自定义 <code>BitSet</code> 类</li><li><strong>Set/Map</strong>: 适合稀疏场景</li><li><strong>BigInt</strong>: 适合极大规模位图</li></ol><p>每种方法内部的数据结构都不一致，下面整理了它们的底层原理、性能对比和适用场景。</p><h2 id="数据结构洞悉" tabindex="-1">数据结构洞悉 <a class="header-anchor" href="#数据结构洞悉" aria-label="Permalink to &quot;数据结构洞悉&quot;">​</a></h2><h3 id="array-n-fill-false" tabindex="-1">Array(n).fill(false) <a class="header-anchor" href="#array-n-fill-false" aria-label="Permalink to &quot;Array(n).fill(false)&quot;">​</a></h3><p><code>Array</code> 作为 JavaScript 的内置对象，一般的 <code>Array</code> 是一个动态数组，底层实现通常是一个连续的内存块，存储着元素的引用。对于 <code>Array(n).fill(false)</code>，每个元素都是一个布尔值 <code>false</code> 的引用。</p><p>声明一个长度为 <code>n</code> 的一位数组，并用 <code>false</code> 填充：<code>Array(n).fill(false)</code>，会创建一个长度为 <code>n</code> 的数组，并将每个元素初始化为 <code>false</code>。这种方法的内存占用较大，因为每个元素都是一个独立的布尔值对象。</p><p>也可以快速的建立二维数组：<code>Array.from({ length: m }, () =&gt; Array(n).fill(false))</code>，这会创建一个 <code>m x n</code> 的二维数组，每个元素都是 <code>false</code>。</p><p>其内存结构分为在栈上的数组对象和在堆上的布尔值对象。其内存可以看为： <img src="'+o+'" alt="Array内存结构示意图"></p>',10)]))}const S=r(c,[["render",l]]);export{f as __pageData,S as default};
